{% if request.path contains "end-of-season-sale" %}
  <script>
    (function () {
      function applyBannerStyle() {
        // getElementsByClassName expects the class name ONLY (no dot)
        var banners = document.getElementsByClassName("section-spacing--tight");
        if (!banners || banners.length === 0) {
          // nothing found — nothing to do
          return;
        }

        // apply to all matches (safer than only the first)
        for (var i = 0; i < banners.length; i++) {
          banners[i].style.backgroundColor = "#C20000";
          // Example: set text color inside banner so red background is visible
          banners[i].style.color = "#fff";
        }
      }

      // Call immediately if DOM is already ready, otherwise wait
      if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", applyBannerStyle);
      } else {
        applyBannerStyle();
      }
    })();
  </script>
{% endif %}

{% if collection.metafields.custom.seo_metadata != blank %}
  <div class="collection-seo-wrapper">
    <div class="collection-seo-container">
      <div class="collection-seo-metadata" id="seoContent">
        {{ collection.metafields.custom.seo_metadata | metafield_tag }}
      </div>
    </div>
  </div>
{% endif %}

<style>
.collection-seo-wrapper {
  width: 100%;
  margin: 40px auto 60px;
  padding: 0 20px;
}

.collection-seo-container {
  position: relative;
  background: transparent;
}

.collection-seo-metadata {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  color: #666;
  line-height: 1.6;
  height: 350px;
  overflow-y: auto;
  padding: 20px;
  scroll-behavior: smooth;
  scrollbar-width: thin;
  scrollbar-color: #ccc transparent;
}

.collection-seo-metadata::-webkit-scrollbar {
  width: 4px;
}

.collection-seo-metadata::-webkit-scrollbar-track {
  background: transparent;
}

.collection-seo-metadata::-webkit-scrollbar-thumb {
  background-color: #ccc;
  border-radius: 4px;
}

/* Typography */
.collection-seo-metadata h1 {
  font-size: 20px;
  font-weight: 600;
  color: #333;
  margin: 0 0 14px 0;
  line-height: 1.4;
  letter-spacing: -0.01em;
}

.collection-seo-metadata h2 {
  font-size: 17px;
  font-weight: 600;
  color: #444;
  margin: 24px 0 12px 0;
  line-height: 1.4;
}

.collection-seo-metadata h3 {
  font-size: 15px;
  font-weight: 600;
  color: #555;
  margin: 20px 0 10px 0;
  line-height: 1.4;
}

.collection-seo-metadata p {
  font-size: 13px;
  color: #666;
  margin: 0 0 12px 0;
  line-height: 1.6;
}

.collection-seo-metadata p:last-child {
  margin-bottom: 0;
}

.collection-seo-metadata ul,
.collection-seo-metadata ol {
  margin: 0 0 12px 0;
  padding-left: 20px;
}

.collection-seo-metadata li {
  font-size: 13px;
  color: #666;
  margin-bottom: 6px;
  line-height: 1.6;
}

.collection-seo-metadata a {
  color: #555;
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: all 0.2s ease;
}

.collection-seo-metadata a:hover {
  color: #333;
  border-bottom-color: #999;
}

.collection-seo-metadata strong {
  font-weight: 600;
  color: #444;
}

/* Tablet */
@media (max-width: 1024px) {
  .collection-seo-wrapper {
    margin: 32px auto 48px;
    padding: 0 16px;
  }

  .collection-seo-metadata {
    height: 350px;
    padding: 16px;
  }

  .collection-seo-metadata h1 { font-size: 18px; }
  .collection-seo-metadata h2 { font-size: 16px; }
  .collection-seo-metadata h3 { font-size: 14px; }
  .collection-seo-metadata p,
  .collection-seo-metadata li { font-size: 12px; }
}

/* Mobile — 90% width, compact margins */
@media (max-width: 767px) {
  .collection-seo-wrapper {
    width: 90%;
    margin: 16px auto 24px;
    padding: 0;
  }

  .collection-seo-metadata {
    height: 315px; /* 90% of 350px */
    padding: 10px;
  }

  .collection-seo-metadata h1 { font-size: 17px; }
  .collection-seo-metadata h2 { font-size: 15px; }
  .collection-seo-metadata h3 { font-size: 14px; }
  .collection-seo-metadata p,
  .collection-seo-metadata li { font-size: 12px; line-height: 1.55; }
}

/* Small Mobile */
@media (max-width: 480px) {
  .collection-seo-wrapper {
    width: 90%;
    margin: 12px auto 20px;
    padding: 0;
  }

  .collection-seo-metadata {
    height: 315px;
    padding: 8px;
  }

  .collection-seo-metadata h1 { font-size: 16px; }
  .collection-seo-metadata h2 { font-size: 14px; }
  .collection-seo-metadata p,
  .collection-seo-metadata li { font-size: 11px; }
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  .collection-seo-metadata {
    scroll-behavior: auto;
  }
  .collection-seo-metadata a {
    transition: none;
  }
}

/* Print */
@media print {
  .collection-seo-metadata {
    height: auto !important;
    overflow: visible !important;
  }
}
</style>

{%- if collection.metafields.custom.collection_meta_field.value != blank -%}
  <section class="pf-faq">
    <div class="pf-faq__inner">
      <h2 class="pf-faq__title">FAQs</h2>
      <div class="pf-faq__list">
        {%- for faq in collection.metafields.custom.collection_meta_field.value -%}
          {%- if faq.tilte != blank and faq.description != blank -%}
            {%- render 'accordion', title: faq.tilte, content: faq.description, prose_content: true, open: false -%}
          {%- endif -%}
        {%- endfor -%}
      </div>
    </div>
  </section>

  <style>
    .pf-faq { width: 100%; padding: clamp(32px, 5vw, 60px) 16px; background: transparent; color: inherit; }
    .pf-faq__inner { max-width: 880px; margin: 0 auto; }
    .pf-faq__title { text-align: left; margin: 0 0 clamp(20px, 3vw, 32px); font-size: clamp(22px, 3vw, 32px); font-weight: 500; line-height: 1.2; }
    .pf-faq__list { display: flex; flex-direction: column; }
    .pf-faq__list .accordion__content,
    .pf-faq__list .accordion-content,
    .pf-faq__list [class*="accordion"] [class*="content"],
    .pf-faq__list .prose,
    .pf-faq__list .rte { text-align: left !important; }
    .pf-faq__list p { text-align: left !important; margin: 0 0 8px; }
  </style>
{%- endif -%}
